<script setup lang="ts">
// 富化人工标注 / 校正工作台抽屉。
// 两种入口复用同一套分型表单：
//   1. 审核流（reviewMode）：从待审队列进入，基于 AI 行校正后「保存并下一条」，或驳回（可带理由）；
//   2. 人工标注（状态页入口）：题未跑过也能直接人工定稿。
// 保存后后端追加 source=human 的定稿行（append-only），公开/内部读取自然取最新人工行；
// 重判时人工已定稿的类型不会被 AI 覆盖。
import { ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import {
  GetEnrichCuratorContext,
  PostEnrichAnnotationSave,
  PostEnrichReviewSet,
} from "@/apis/problem-enrichment";
import type { CuratorContext, EnrichReviewItem } from "@/types/problem-enrichment";
import { handleGotoProblem } from "@/util/router";

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;

const props = defineProps<{
  visible: boolean;
  problemId: number;
  initialTaskType: string;
  reviewMode: boolean;
}>();

const emit = defineEmits<{
  (e: "update:visible", v: boolean): void;
  // advance=true 表示审核流处理完一条、希望父组件切到下一条待审
  (e: "saved", payload: { taskType: string; advance: boolean }): void;
  (e: "rejected", payload: { annotationId: number }): void;
}>();

const TASK_TYPES = [
  { value: "summary", label: "摘要（公开）" },
  { value: "tags", label: "标签（公开）" },
  { value: "difficulty", label: "难度（公开）" },
  { value: "quality", label: "质量（内部）" },
  { value: "suggestion", label: "改进建议（内部）" },
];

const gradeOptions = [
  { label: "1 · 入门", value: 1 },
  { label: "2 · 普及", value: 2 },
  { label: "3 · 提高", value: 3 },
  { label: "4 · 省选", value: 4 },
  { label: "5 · NOI", value: 5 },
];

const difficultyDims = [
  { key: "thinking", label: "思维难度" },
  { key: "algorithm", label: "算法要求" },
  { key: "implementation", label: "实现难度" },
  { key: "pitfalls", label: "陷阱复杂度" },
];

const qualityDims = [
  { key: "completeness", label: "题面完整性" },
  { key: "examples", label: "样例充分性" },
  { key: "judge_config", label: "判题配置", rule: true },
  { key: "data_strength", label: "数据强度", rule: true },
];

const dimensionOptions = [
  { label: "数据范围/约束", value: "constraints" },
  { label: "输入输出", value: "io" },
  { label: "样例", value: "examples" },
  { label: "判题配置", value: "judge_config" },
  { label: "测试数据", value: "data" },
  { label: "题面表述", value: "statement" },
];
const severityOptions = [
  { label: "提示 info", value: "info" },
  { label: "警告 warn", value: "warn" },
  { label: "阻断 block", value: "block" },
];
const suggestionStatusOptions = [
  { label: "待处理", value: "open" },
  { label: "已采纳", value: "done" },
  { label: "已忽略", value: "ignored" },
];

const loading = ref(false);
const saving = ref(false);
const ctx = ref<CuratorContext | null>(null);
const activeType = ref("summary");
// 每种类型一份可编辑草稿
const drafts = ref<Record<string, any>>({});
// 每种类型当前最新标注行（保存时作为被校正的基底 annotation_id）
const baseMap = ref<Record<string, EnrichReviewItem>>({});
const goldenChecked = ref<Record<string, boolean>>({});
const note = ref("");

const close = () => emit("update:visible", false);

const emptyDraft = (type: string): any => {
  switch (type) {
    case "summary":
      return { oneliner: "", io_points: "", scale: "" };
    case "tags":
      return { raw: [], canonical: [] };
    case "difficulty":
      return {
        overall: 3,
        thinking: 3,
        algorithm: 3,
        implementation: 3,
        pitfalls: 3,
        evidence: { thinking: "", algorithm: "", implementation: "", pitfalls: "" },
      };
    case "quality":
      return {
        overall: 3,
        completeness: 3,
        examples: 3,
        judge_config: 3,
        data_strength: 3,
        sources: { completeness: "human", examples: "human", judge_config: "human", data_strength: "human" },
        evidence: { completeness: "", examples: "", judge_config: "", data_strength: "" },
      };
    case "suggestion":
      return { items: [] };
    default:
      return {};
  }
};

const load = async () => {
  if (!props.problemId) {
    return;
  }
  loading.value = true;
  try {
    const res = await GetEnrichCuratorContext(props.problemId);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    // 后端 annotations / tag_names 等集合在缺省时可能为 null，统一兜底，避免遍历或模板读取 .length 时崩溃
    const annotations = res.data?.annotations ?? [];
    if (res.data) {
      ctx.value = {
        ...res.data,
        annotations,
        problem: res.data.problem
          ? { ...res.data.problem, tag_names: res.data.problem.tag_names ?? [] }
          : res.data.problem,
      };
    }
    baseMap.value = {};
    drafts.value = {};
    goldenChecked.value = {};
    for (const t of TASK_TYPES.map((x) => x.value)) {
      drafts.value[t] = emptyDraft(t);
    }
    for (const a of annotations) {
      baseMap.value[a.task_type] = a;
      drafts.value[a.task_type] = JSON.parse(JSON.stringify(a.payload ?? {}));
      goldenChecked.value[a.task_type] = !!a.golden;
    }
    activeType.value = TASK_TYPES.some((t) => t.value === props.initialTaskType) ? props.initialTaskType : "summary";
    note.value = "";
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载题目上下文失败");
  } finally {
    loading.value = false;
  }
};

watch(
  () => [props.visible, props.problemId, props.initialTaskType],
  () => {
    if (props.visible && props.problemId) {
      load();
    }
  }
);

const addSuggestion = () => {
  drafts.value.suggestion.items.push({
    dimension: "statement",
    severity: "info",
    evidence: "",
    suggestion: "",
    status: "open",
  });
};
const removeSuggestion = (i: number) => {
  drafts.value.suggestion.items.splice(i, 1);
};

// 组装并校验当前类型 payload；返回 null 表示校验未过
const buildPayload = (type: string): Record<string, unknown> | null => {
  const d = drafts.value[type];
  if (type === "summary") {
    const p = {
      oneliner: (d.oneliner ?? "").trim(),
      io_points: (d.io_points ?? "").trim(),
      scale: (d.scale ?? "").trim(),
    };
    if (!p.oneliner || !p.io_points || !p.scale) {
      ShowTextTipsError(globalProperties, "摘要的题意 / 输入输出 / 数据规模三段都不能为空");
      return null;
    }
    return p;
  }
  if (type === "tags") {
    const clean = (arr: string[]) =>
      (arr ?? []).map((s) => s.trim()).filter(Boolean).filter((v, i, a) => a.indexOf(v) === i);
    const raw = clean(d.raw);
    const canonical = clean(d.canonical);
    if (raw.length === 0 && canonical.length === 0) {
      ShowTextTipsError(globalProperties, "请至少填写一个标签");
      return null;
    }
    return { raw, canonical, candidate: [] };
  }
  if (type === "difficulty") {
    const overall = d.overall || Math.max(d.thinking, d.algorithm);
    return {
      overall,
      thinking: d.thinking,
      algorithm: d.algorithm,
      implementation: d.implementation,
      pitfalls: d.pitfalls,
      evidence: {
        thinking: (d.evidence?.thinking ?? "").trim(),
        algorithm: (d.evidence?.algorithm ?? "").trim(),
        implementation: (d.evidence?.implementation ?? "").trim(),
        pitfalls: (d.evidence?.pitfalls ?? "").trim(),
      },
    };
  }
  if (type === "quality") {
    const base = baseMap.value.quality?.payload as any;
    const avg = Math.round((d.completeness + d.examples + d.judge_config + d.data_strength) / 4);
    return {
      overall: d.overall >= 1 && d.overall <= 5 ? d.overall : avg,
      completeness: d.completeness,
      examples: d.examples,
      judge_config: d.judge_config,
      data_strength: d.data_strength,
      sources: d.sources ?? base?.sources ?? emptyDraft("quality").sources,
      evidence: d.evidence ?? base?.evidence ?? emptyDraft("quality").evidence,
    };
  }
  if (type === "suggestion") {
    const items = (d.items ?? [])
      .map((it: any) => ({
        dimension: it.dimension,
        severity: it.severity,
        evidence: (it.evidence ?? "").trim(),
        suggestion: (it.suggestion ?? "").trim(),
        status: it.status || "open",
      }))
      .filter((it: any) => it.suggestion);
    return { items };
  }
  return null;
};

const save = async (advance: boolean) => {
  const type = activeType.value;
  const payload = buildPayload(type);
  if (!payload) {
    return;
  }
  saving.value = true;
  try {
    const base = baseMap.value[type];
    const res = await PostEnrichAnnotationSave({
      problem_id: props.problemId,
      task_type: type,
      annotation_id: base?.id ?? 0,
      payload,
      golden: goldenChecked.value[type] ?? false,
      note: note.value.trim(),
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, "人工定稿已保存");
    emit("saved", { taskType: type, advance });
    if (advance) {
      // 父组件会换题/换类型，watch 自动重载；这里不重复 load
      return;
    }
    await load();
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "保存失败");
  } finally {
    saving.value = false;
  }
};

const reject = async () => {
  const type = activeType.value;
  const base = baseMap.value[type];
  if (!base || base.review_status !== "pending") {
    ShowTextTipsError(globalProperties, "当前类型没有待驳回的 AI 标注");
    return;
  }
  saving.value = true;
  try {
    const res = await PostEnrichReviewSet(base.id, "rejected", note.value.trim());
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, "已驳回");
    emit("rejected", { annotationId: base.id });
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    saving.value = false;
  }
};

const gotoProblem = () => {
  if (ctx.value?.problem.key) {
    handleGotoProblem(ctx.value.problem.key);
  }
};
</script>

<template>
  <t-drawer
    :visible="visible"
    :header="reviewMode ? '审核 · 人工校正定稿' : '人工标注定稿'"
    size="90%"
    :footer="true"
    :close-on-overlay-click="false"
    @close="close"
  >
    <t-loading :loading="loading">
      <div v-if="ctx" class="curator">
        <t-row :gutter="16">
          <!-- 左：题面上下文 -->
          <t-col :xs="24" :md="9" :lg="8">
            <div class="ctx-panel">
              <div class="ctx-head">
                <t-button variant="text" @click="gotoProblem">
                  {{ ctx.problem.key || `#${ctx.problem.id}` }} · {{ ctx.problem.title }}
                </t-button>
              </div>
              <div class="ctx-meta">
                时限 {{ ctx.problem.time_limit }}ms · 内存 {{ ctx.problem.memory_limit }}KB ·
                {{ ctx.problem.judge_type === 1 ? "SPJ 特殊判题" : "普通比较判题" }}
              </div>
              <div v-if="ctx.problem.tag_names.length" class="ctx-tags">
                <t-tag v-for="n in ctx.problem.tag_names" :key="n" size="small" variant="outline">{{ n }}</t-tag>
              </div>
              <div class="ctx-statement">{{ ctx.problem.description }}</div>
            </div>
          </t-col>

          <!-- 右：分型编辑表单 -->
          <t-col :xs="24" :md="15" :lg="16">
            <t-tabs v-model="activeType">
              <!-- 摘要 -->
              <t-tab-panel value="summary" label="摘要">
                <t-alert
                  theme="warning"
                  message="剧透红线：只能描述问题本身，不得出现算法名、解法、复杂度或数据结构提示。"
                  class="curator-alert"
                />
                <div class="field">
                  <label class="field-label">一句话题意</label>
                  <t-textarea v-model="drafts.summary.oneliner" :autosize="{ minRows: 2 }" />
                </div>
                <div class="field">
                  <label class="field-label">输入 / 输出要点</label>
                  <t-textarea v-model="drafts.summary.io_points" :autosize="{ minRows: 2 }" />
                </div>
                <div class="field">
                  <label class="field-label">数据规模</label>
                  <t-textarea v-model="drafts.summary.scale" :autosize="{ minRows: 2 }" />
                </div>
              </t-tab-panel>

              <!-- 标签 -->
              <t-tab-panel value="tags" label="标签">
                <div class="field">
                  <label class="field-label">正式标签（受控词表，用于检索）</label>
                  <t-tag-input v-model="drafts.tags.canonical" placeholder="输入正式标签后回车" />
                </div>
                <div class="field">
                  <label class="field-label">自由标签（AI 原始写法，会尝试归并为别名）</label>
                  <t-tag-input v-model="drafts.tags.raw" placeholder="输入自由标签后回车" />
                </div>
              </t-tab-panel>

              <!-- 难度 -->
              <t-tab-panel value="difficulty" label="难度">
                <div class="field">
                  <label class="field-label">综合难度档</label>
                  <t-select v-model="drafts.difficulty.overall" :options="gradeOptions" style="max-width: 240px" />
                </div>
                <div v-for="dim in difficultyDims" :key="dim.key" class="score-row">
                  <span class="score-label">{{ dim.label }}</span>
                  <t-slider
                    v-model="drafts.difficulty[dim.key]"
                    :min="1"
                    :max="5"
                    :step="1"
                    class="score-slider"
                  />
                  <span class="score-value">{{ drafts.difficulty[dim.key] }}</span>
                </div>
                <div v-for="dim in difficultyDims" :key="dim.key" class="field">
                  <label class="field-label">证据 · {{ dim.label }}</label>
                  <t-textarea
                    v-model="drafts.difficulty.evidence[dim.key]"
                    :autosize="{ minRows: 1, maxRows: 3 }"
                    placeholder="引用题面中支撑该评分的原文/信号"
                  />
                </div>
              </t-tab-panel>

              <!-- 质量 -->
              <t-tab-panel value="quality" label="质量">
                <div class="field">
                  <label class="field-label">综合质量档</label>
                  <t-select v-model="drafts.quality.overall" :options="gradeOptions" style="max-width: 240px" />
                </div>
                <div v-for="dim in qualityDims" :key="dim.key" class="score-row">
                  <span class="score-label">
                    {{ dim.label }}
                    <t-tag v-if="dim.rule" size="small" theme="default" variant="outline">规则判定</t-tag>
                  </span>
                  <t-slider
                    v-model="drafts.quality[dim.key]"
                    :min="1"
                    :max="5"
                    :step="1"
                    class="score-slider"
                  />
                  <span class="score-value">{{ drafts.quality[dim.key] }}</span>
                </div>
                <t-divider align="left">判定依据（来自规则 / 模型，人工可参考）</t-divider>
                <t-descriptions
                  :column="1"
                  bordered
                  size="small"
                  :data="[
                    { label: '题面完整性', value: drafts.quality.evidence?.completeness || '—' },
                    { label: '样例充分性', value: drafts.quality.evidence?.examples || '—' },
                    { label: '判题配置', value: drafts.quality.evidence?.judge_config || '—' },
                    { label: '数据强度', value: drafts.quality.evidence?.data_strength || '—' },
                  ]"
                />
              </t-tab-panel>

              <!-- 改进建议 -->
              <t-tab-panel value="suggestion" label="改进建议">
                <div v-for="(it, i) in drafts.suggestion.items" :key="i" class="sugg-item">
                  <t-row :gutter="8">
                    <t-col :xs="12" :md="6">
                      <t-select v-model="it.dimension" :options="dimensionOptions" placeholder="维度" />
                    </t-col>
                    <t-col :xs="12" :md="5">
                      <t-select v-model="it.severity" :options="severityOptions" placeholder="严重度" />
                    </t-col>
                    <t-col :xs="12" :md="5">
                      <t-select v-model="it.status" :options="suggestionStatusOptions" placeholder="状态" />
                    </t-col>
                    <t-col :xs="12" :md="8">
                      <t-input v-model="it.evidence" placeholder="题面证据（可选）" />
                    </t-col>
                  </t-row>
                  <t-textarea
                    v-model="it.suggestion"
                    :autosize="{ minRows: 1, maxRows: 3 }"
                    placeholder="具体改进建议"
                    class="sugg-text"
                  />
                  <t-button size="small" variant="text" theme="danger" @click="removeSuggestion(i)">
                    删除该条
                  </t-button>
                </div>
                <t-button variant="outline" block class="sugg-add" @click="addSuggestion">+ 添加一条建议</t-button>
                <div v-if="drafts.suggestion.items.length === 0" class="sugg-empty">暂无改进建议</div>
              </t-tab-panel>
            </t-tabs>
          </t-col>
        </t-row>
      </div>
    </t-loading>

    <template #footer>
      <div class="curator-footer">
        <div class="curator-footer-left">
          <t-checkbox v-model="goldenChecked[activeType]">同时冻结为黄金集基准</t-checkbox>
          <t-input
            v-model="note"
            placeholder="校正说明 / 驳回理由（可选，留痕）"
            style="width: 260px"
            class="curator-note"
          />
        </div>
        <t-space>
          <t-button variant="outline" @click="close">关闭</t-button>
          <t-button v-if="reviewMode" theme="danger" variant="outline" :loading="saving" @click="reject">
            驳回并下一条
          </t-button>
          <t-button v-if="reviewMode" theme="default" variant="outline" :loading="saving" @click="save(false)">
            仅保存
          </t-button>
          <t-button theme="primary" :loading="saving" @click="reviewMode ? save(true) : save(false)">
            {{ reviewMode ? "保存校正并下一条" : "保存人工定稿" }}
          </t-button>
        </t-space>
      </div>
    </template>
  </t-drawer>
</template>

